def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def regions(n, seps):
        out = []
        start = 0
        for s in seps:
            if start < s:
                out.append(list(range(start, s)))
            start = s + 1
        if start < n:
            out.append(list(range(start, n)))
        return out

    rows, cols = regions(h, row_seps), regions(w, col_seps)
    out = [r[:] for r in grid]
